import {escape} from './workspace-shared.js';
import {courseIcon} from './course-overview.js';
import {unitPosition} from './unit-position.mjs';

export function unitMeter(course,now) {
  const p=unitPosition(course,now);
  return `<div class="unit-meter"><div><span>Unit timeline</span><strong>${p.held} of ${p.total} lessons held</strong></div><span class="unit-meter-track"><progress max="${p.total || 1}" value="${p.held}" aria-label="Unit timeline: ${p.held} of ${p.total} lessons held; one segment per lesson"></progress><span class="unit-meter-segments" aria-hidden="true">${Array.from({length:p.total},()=>'<i></i>').join('')}</span></span></div>`;
}

export function learningWorkspace(data,notebookURL) {
  const c=data.course,p=unitPosition(c,data.serverNow),current=p.current<0?0:p.current;
  const state=l=>l.status==='cancelled'?'Cancelled':l.endsAt!==null && Number.isFinite(l.endsAt) && l.endsAt<=data.serverNow?'Lesson held':'Upcoming';
  const date=l=>l.date?new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(l.date+'T12:00:00Z')):'Date to be set';
  return `<div class="learning-course-intro"><div><span class="lms-kicker">${escape(data.className)}</span>${c.description?`<p>${escape(c.description)}</p>`:''}</div>${unitMeter(c,data.serverNow)}</div>
    <div class="learning-layout"><aside class="learning-rail"><h3>Lesson plan <span>${c.lessons.length}</span></h3><label class="learning-lesson-picker"><span>Lesson</span><select data-learning-picker aria-label="Choose a lesson">${c.lessons.map((l,i)=>`<option value="${i}" ${i===current?'selected':''}>${l.number || i+1}. ${escape(l.title)}</option>`).join('')}</select></label><nav aria-label="Course lessons">${c.lessons.map((l,i)=>`<button type="button" class="learning-step" data-learning-step="${i}" aria-controls="learning-lesson-${i}" ${i===current?'aria-current="step"':''}><span class="learning-step-number">${String(l.number || i+1).padStart(2,'0')}</span><span><strong>${escape(l.title)}</strong><small>${escape(state(l))}${l.date?' · '+escape(date(l)):''}</small></span></button>`).join('')}</nav><a class="learning-notebook-shortcut" href="${escape(notebookURL)}">${courseIcon('book')}<span>${data.canTakeQuiz?'My notebook':'Live notebook'}</span><span aria-hidden="true">↗</span></a></aside>
    <div class="learning-stage">${c.lessons.map((l,i)=>`<article class="learning-lesson ${l.status==='cancelled'?'is-cancelled':''}" id="learning-lesson-${i}" data-learning-lesson="${i}" ${i===current?'':'hidden'}><header class="learning-lesson-heading"><p class="lms-kicker">Lesson ${l.number || i+1} <span>of ${c.lessons.length}</span></p><h3 tabindex="-1">${escape(l.title)}</h3>${l.goal?`<p>${escape(l.goal)}</p>`:''}${l.status==='cancelled'?'<span class="overview-cancelled">Cancelled</span>':''}</header>
    <div class="learning-activities"><section class="learning-activity"><div class="learning-activity-label">${courseIcon('quiz')}<span>Before class</span></div><div class="learning-activity-content"><section data-lesson-quiz-summary="${escape(l.id)}"></section>${l.reading?`<div class="learning-reading"><h4>Reading &amp; preparation</h4><p>${escape(l.reading)}</p></div>`:''}</div></section>
    <section class="learning-activity learning-live"><div class="learning-activity-label">${courseIcon('video')}<span>Live lesson</span></div><div class="learning-activity-content"><h4>${escape(date(l))}${l.date && (l.startTime || c.startTime)?' · '+escape(l.startTime || c.startTime):''}</h4><p class="learning-time">${l.lessonMinutes ?? c.lessonMinutes} minutes · ${escape(c.timeZone)}</p>${l.section?`<p>${escape(l.section)}</p>`:''}${l.rescheduledFrom?`<p class="planner-hint">Rescheduled from ${escape(l.rescheduledFrom.date)} · ${escape(l.rescheduledFrom.startTime)}</p>`:''}${l.billing?`<p class="lesson-billing">${escape(l.billing)}</p>`:''}<a class="teacher-button" href="${escape(notebookURL)}">Open notebook <span aria-hidden="true">↗</span></a></div></section>
    <section class="learning-activity"><div class="learning-activity-label">${courseIcon('pencil')}<span>After class</span></div><div class="learning-activity-content"><h4>Homework</h4><p>${escape(l.homework || 'No homework assigned yet.')}</p>${l.report?`<a class="learning-feedback-ready" href="#learning-feedback-${i}">Read feedback ↓</a>`:'<p class="learning-muted">Your teacher’s feedback will appear below after it is published.</p>'}</div></section></div>
    <section class="learning-report" id="learning-feedback-${i}" tabindex="-1" data-timeline-lesson="${escape(l.id)}" ${l.report?'':'hidden'}></section><footer class="learning-lesson-footer"><button type="button" class="text-button" data-learning-step="${i-1}" ${i===0?'disabled':''}>← Previous lesson</button><span>${i+1} / ${c.lessons.length}</span><button type="button" class="text-button" data-learning-step="${i+1}" ${i===c.lessons.length-1?'disabled':''}>Next lesson →</button></footer></article>`).join('') || '<div class="empty-classes"><h3>Your lessons are being prepared.</h3><p>Your teacher’s lesson plan will appear here.</p></div>'}</div></div>`;
}
